<?php
declare(strict_types=1);
if (PHP_SAPI !== 'cli') { http_response_code(403); exit("CLI only\n"); }
require_once __DIR__ . '/../includes/db.php';
$db = getDB();
$db->beginTransaction();
try {
    $category = $db->query("SELECT c.id FROM categories c JOIN categories p ON p.id = c.parent_id WHERE c.slug = 'party-san' AND p.slug = 'festival-news' LIMIT 1")->fetch(PDO::FETCH_ASSOC);
    if (!$category) { throw new RuntimeException('Kategorie Festival-News > Party San nicht gefunden.'); }
    $title = base64_decode('UGFydHkuU2FuIE9wZW4gQWlyIDIwMjY6IFZvcnNjaGF1IGF1ZiBkcmVpIFRhZ2UgVG9kZXNhY2tlcg==', true);
    $slug = base64_decode('cGFydHktc2FuLW9wZW4tYWlyLTIwMjYtdm9yc2NoYXU=', true);
    $content = base64_decode('', true);
    $excerpt = base64_decode('Vm9tIDYuIGJpcyA4LiBBdWd1c3QgMjAyNiBrZWhydCBkYXMgUGFydHkuU2FuIE9wZW4gQWlyIGF1ZiBkZW4gRmx1Z3BsYXR6IE9iZXJtZWhsZXIgenVyw7xjay4gVGVzdGFtZW50LCBBbW9ycGhpcyB1bmQgSHlwb2NyaXN5IGbDvGhyZW4gZGFzIEJpbGxpbmcgbWl0IDU3IGJlc3TDpHRpZ3RlbiBCYW5kcyBhbi4=', true);
    $image = base64_decode('L2Fzc2V0cy9pbWcvdXBsb2Fkcy9wYXJ0eS1zYW4vcGFydHktc2FuLW9wZW4tYWlyLTIwMjYtdm9yc2NoYXUucG5n', true);
    if ($title === false || $slug === false || $content === false || $excerpt === false || $image === false) {
        throw new RuntimeException('Artikelinhalt konnte nicht dekodiert werden.');
    }
    $sql = "INSERT INTO articles (title, slug, content, excerpt, category_id, author, featured_image, status, created_at, updated_at)
            VALUES (:title, :slug, :content, :excerpt, :category_id, :author, :image, 'published', NOW(), NOW())
            ON DUPLICATE KEY UPDATE title=VALUES(title), content=VALUES(content), excerpt=VALUES(excerpt),
              category_id=VALUES(category_id), author=VALUES(author), featured_image=VALUES(featured_image),
              status='published', updated_at=NOW()";
    $stmt = $db->prepare($sql);
    $stmt->execute([
        ':title' => $title, ':slug' => $slug, ':content' => $content,
        ':excerpt' => $excerpt, ':category_id' => (int)$category['id'],
        ':author' => 'Michael Jakob', ':image' => $image,
    ]);
    $check = $db->prepare("SELECT a.id,a.slug,a.status,a.category_id,c.name category_name,p.name parent_name,LENGTH(a.content) content_bytes FROM articles a JOIN categories c ON c.id=a.category_id LEFT JOIN categories p ON p.id=c.parent_id WHERE a.slug=:slug");
    $check->execute([':slug' => $slug]);
    $row = $check->fetch(PDO::FETCH_ASSOC);
    if (!$row || $row['status'] !== 'published' || $row['category_name'] !== 'Party San' || $row['parent_name'] !== 'Festival-News') {
        throw new RuntimeException('Verifikation nach dem Einfügen fehlgeschlagen.');
    }
    $db->commit();
    echo json_encode($row, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES), PHP_EOL;
} catch (Throwable $e) {
    if ($db->inTransaction()) { $db->rollBack(); }
    fwrite(STDERR, $e->getMessage() . PHP_EOL);
    exit(1);
}
